"use client"

import { useState, useEffect } from "react"
import { Calendar, Activity, TrendingUp } from "lucide-react"
import DatePicker from "react-datepicker"
import { format, subDays } from "date-fns"
import { es } from "date-fns/locale"
import { fetchProductos } from "../services/api"
import ZoomableImage from "./ZoomableImage"
import "react-datepicker/dist/react-datepicker.css"
import { motion } from "framer-motion";

const GasesSection = ({ loading: initialLoading }) => {
  const [selectedDate, setSelectedDate] = useState(new Date())
  const [productos, setProductos] = useState([])
  const [loading, setLoading] = useState(initialLoading)

  const gasTypes = [
    {
      id: "CO2",
      name: "Dióxido de Carbono",
      symbol: "CO₂",
      filename: "CO2_webvisualizer_v4.png",
      color: "text-red-600",
      bgColor: "bg-red-50",
      borderColor: "border-red-200",
      description: "Concentración de CO₂ medida por el analizador Picarro",
    },
    {
      id: "CH4",
      name: "Metano",
      symbol: "CH₄",
      filename: "CH4_webvisualizer_v4.png",
      color: "text-green-600",
      bgColor: "bg-green-50",
      borderColor: "border-green-200",
      description: "Concentración de CH₄ medida por el analizador Picarro",
    },
  ]

  useEffect(() => {
    loadGasesData()
  }, [selectedDate])

  const loadGasesData = async () => {
    try {
      setLoading(true)
      const dateStr = format(selectedDate, "yyyy-MM-dd")
      const response = await fetchProductos({
        tipo: "MedicionAire",
        fecha: dateStr,
      })

      setProductos(response.results || response)
    } catch (error) {
      console.error("Error loading gases data:", error)
    } finally {
      setLoading(false)
    }
  }

  const getImageForGas = (gasType) => {
    return productos.find((p) => p.nombre_archivo === gasType.filename)
  }

  return (
    <motion.div
      initial={{ opacity: 0, y: 40 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.7, ease: 'easeOut' }}
      className="bg-white/90 rounded-2xl shadow-2xl p-8 flex flex-col items-center gap-6 min-h-[220px]"
      style={{ backdropFilter: 'blur(4px)' }}
    >
      <Activity className="h-12 w-12 text-green-600 mb-2" />
      <div className="text-3xl font-bold text-gray-800 mb-1">Gases Atmosféricos</div>
      <div className="text-2xl font-extrabold text-green-700 mb-1">{productos.length > 0 ? `Tipos: ${productos.length}` : "Sin datos recientes"}</div>
      <div className="w-full grid grid-cols-1 md:grid-cols-2 gap-4 mt-4">
        {gasTypes.map((gas) => (
          <motion.div
            key={gas.id}
            initial={{ opacity: 0, y: 40 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.9, ease: 'easeOut' }}
            className={`rounded-xl p-6 border ${gas.borderColor} bg-white/80 flex flex-col items-center shadow-md`}
            style={{ backdropFilter: 'blur(2px)' }}
          >
            <div className={`text-4xl mb-2 ${gas.color}`}>{gas.symbol}</div>
            <div className="font-bold text-lg mb-1">{gas.name}</div>
            <div className="text-gray-500 text-sm mb-2">{gas.description}</div>
            <div className="text-xs text-gray-400">{gas.filename}</div>
          </motion.div>
        ))}
      </div>
    </motion.div>
  )
}

export default GasesSection
